// SVG-tekst van een icoon (of grote letter als terugval) in een kleur en dekking.
function medicijn_icoonSvg(icoon, letter, kleur, dekking) {
    const def = icoon && MEDICIJN_ICONEN[icoon];
    const vorm = def ? def.svg
        : `<text x="24" y="38" text-anchor="middle" font-family="Arial, sans-serif" font-weight="700" font-size="40">${
            String(letter || '?').trim().charAt(0).toUpperCase().replace(/[<>&"']/g, '')}</text>`;
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" fill="${kleur}" fill-opacity="${dekking}">${vorm}</svg>`;
}
